"""Contratos da UI G10.3 em Chromium; Auth/RPC simulados, sem Supabase real."""
import unittest
import test_event_planning_browser as base
class G103GovernanceBrowserTests(unittest.TestCase):
 setUpClass=classmethod(base.EventPlanningBrowserTests.setUpClass.__func__);tearDownClass=classmethod(base.EventPlanningBrowserTests.tearDownClass.__func__)
 setUp=base.EventPlanningBrowserTests.setUp;tearDown=base.EventPlanningBrowserTests.tearDown
 go=base.EventPlanningBrowserTests.go;login=base.EventPlanningBrowserTests.login;choose=base.EventPlanningBrowserTests.choose;form=base.EventPlanningBrowserTests.form;save=base.EventPlanningBrowserTests.save;calendar=base.EventPlanningBrowserTests.calendar
 def policy(self,approve=False,force_password=False):
  self.page.evaluate('''({approve,force})=>{const prior=window.fetch;window.fetch=async(input,options={})=>{const url=new URL(typeof input==='string'?input:input.url),name=url.pathname.split('/').pop();
   if(name==='iasdpi_password_change_context')return Response.json({must_change_password:force,aliases:['individual.iasdpi']});
   if(name==='access-assistance'&&JSON.parse(options.body||'{}').action==='change_password')return Response.json({completed:true,login_required:true});
   if(name==='iasdpi_event_approve'){const b=JSON.parse(options.body),e=IASDPIE1Demo.events.get(b.p_id);e.status='published';e.approval_status='approved';e.version++;IASDPIE1Demo.versions.get(e.id).push({version:e.version,status:'published',snapshot:structuredClone(e)});return Response.json(e);}
   const response=await prior(input,options);if(!response.ok||!['iasdpi_events_catalog','iasdpi_event_submit'].includes(name))return response;const data=await response.json();
   if(name==='iasdpi_events_catalog')return Response.json({...data,event_approval_required:true,can_submit_general:true,can_approve_general:approve});
   if(data.event?.program_category==='general'&&!approve){const e=IASDPIE1Demo.events.get(data.event.id);e.status='draft';e.approval_status='pending';const v=IASDPIE1Demo.versions.get(e.id).at(-1);v.status='draft';v.snapshot=structuredClone(e);return Response.json({...data,event:structuredClone(e)});}return Response.json(data);
  };}''',{'approve':approve,'force':force_password})
 def test_leader_general_submission_is_pending_and_not_in_public_calendar(self):
  self.policy();self.login('som.iasdpi');self.form(title='Geral sintético sujeito a aprovação',public='general',organizer='department:00000000-0000-4000-8000-000000000001');self.assertEqual(self.page.locator('#event-editor button[value=published]').inner_text(),'Enviar para aprovação');self.save();self.page.wait_for_function("()=>document.querySelector('#event-save-state')?.textContent.includes('Enviado para aprovação')");self.calendar();self.assertNotIn('Geral sintético sujeito a aprovação',self.page.locator('.scale-calendar').inner_text())
 def test_administrator_can_approve_and_publish_a_pending_event(self):
  self.login();self.form(title='Geral sintético para decisão',public='general');self.save('draft');self.page.evaluate("()=>{const e=[...IASDPIE1Demo.events.values()].find(e=>e.title==='Geral sintético para decisão');e.approval_status='pending';}");self.policy(approve=True);self.page.locator('[data-events-retry]').click();self.page.wait_for_selector('[data-event-approve]');self.page.once('dialog',lambda d:d.accept());self.page.locator('[data-event-approve]').click();self.page.wait_for_function("()=>document.querySelector('#app')?.textContent.includes('Evento aprovado e publicado')");self.calendar();self.assertIn('Geral sintético para decisão',self.page.locator('.scale-calendar').inner_text())
 def test_required_password_change_goes_to_password_form_without_ministry_editor(self):
  self.policy(force_password=True);self.page.evaluate("()=>window.IASDPIConfig=Object.freeze({...IASDPIConfig,responsibilityGovernanceEnabled:true})");self.choose();self.page.fill('#portal-login-form [name=email]','som.iasdpi');self.page.fill('#portal-login-form [name=password]','Demonstracao#2026');self.page.locator('#portal-login-form button').click();self.page.wait_for_selector('#own-password-form');self.assertEqual(self.page.locator('[data-calendar-volunteer]').count(),0);self.assertIn('provisória',self.page.locator('#app').inner_text())
 def test_own_password_form_rejects_mismatch_and_success_requires_new_login(self):
  self.login();self.policy();self.page.evaluate("()=>window.IASDPIConfig=Object.freeze({...IASDPIConfig,responsibilityGovernanceEnabled:true})");self.go('reset-password');self.page.wait_for_selector('#own-password-form');self.page.fill('#own-password-form [name=password]','SyntheticIndividual#2026');self.page.fill('#own-password-form [name=repeat]','DifferentSynthetic#2026');self.page.locator('#own-password-form button').click();self.assertIn('iguais',self.page.locator('[data-password-feedback]').inner_text());self.page.fill('#own-password-form [name=repeat]','SyntheticIndividual#2026');self.page.locator('#own-password-form button').click();self.page.wait_for_function('()=>IASDPIAuth.identityKey()===null')
